cssCode:
.map-pin-wrap {
  position: relative; width: 100px; height: 100px;
  display: flex; align-items: center; justify-content: center;
}
.radar-wave {
  position: absolute;
  width: 20px; height: 20px;
  background: #00ffcc;
  border-radius: 50%;
  animation: radarPulse 2s ease-out infinite;
}
.radar-wave:nth-child(2) { animation-delay: 0.6s; }
.radar-wave:nth-child(3) { animation-delay: 1.2s; }
.map-pin {
  position: relative; z-index: 10;
  width: 24px; height: 24px;
  background: #00ffcc;
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  box-shadow: -2px 2px 10px rgba(0, 255, 204, 0.5);
}
@keyframes radarPulse {
  0% { transform: scale(1); opacity: 0.8; }
  100% { transform: scale(5); opacity: 0; }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'map-pin-wrap';

for(let i=0; i<3; i++) {
  const wave = document.createElement('div');
  wave.className = 'radar-wave';
  wrap.appendChild(wave);
}

const pin = document.createElement('div');
pin.className = 'map-pin';
wrap.appendChild(pin);

c.appendChild(wrap);
